# Verify the bootstrap CI convergence numbers
import json
with open('artifacts/bootstrap_ci_convergence_results.json') as f:
    data = json.load(f)

print('Keys:', list(data.keys()))
for topo in ['exposure', 'iv']:
    if topo in data:
        topo_data = data[topo]
        if isinstance(topo_data, dict):
            for N_key in sorted(topo_data.keys()):
                entry = topo_data[N_key]
                if isinstance(entry, dict):
                    ci_width = entry.get('ci_width', entry.get('mean_ci_width', 'N/A'))
                    print(f'{topo} N={N_key}: ci_width={ci_width}')
"
